TOWN_NAMES = {t["slug"]: t["name"] for t in TOWNS}
COUNTY_NAMES = {c["slug"]: c["name"] for c in COUNTIES}


def county_page(c):
    place = c["name"]
    body = prose_section("Local Knowledge", c["intro_h"], "local-heading", c["intro"])
    body += warn_section(f"Common in {place}", f"Problems We Fix Most in {place}", "warns-heading", c["issues"],
                         sub="If any of these sound familiar, a free inspection will tell you what is causing it.")
    links = [(TOWN_NAMES[s], town_url(s)) for s in c.get("towns", [])]
    if links:
        body += links_section("Where We Work", c["towns_h"], "towns-heading", links,
                              sub="We also serve " + "; ".join(c["towns_text"]) + ".")
    else:
        body += links_section("Where We Work", c["towns_h"], "towns-heading",
                              [("All service areas", AREAS)], sub="Including " + "; ".join(c["towns_text"]) + ".")
    body += services_sections(place)
    return dict(
        path=f"{AREAS}{c['slug']}/", title=c["title"], desc=c["desc"], h1=c["h1"], lead=c["lead"],
        crumbs=[("Service Areas", AREAS), (place, f"{AREAS}{c['slug']}/")],
        form=f"lead-area-{c['slug']}", form_heading=f"Free Estimate in {place}", service=place,
        nav="subnav-areas", body=body, faqs=c["faqs"], faq_key=f"area-{c['slug']}",
        faq_heading=f"{place} Questions", cta=f"Free Estimates Throughout {place}",
        schema=[{"@type": "Service", "name": f"Basement waterproofing and foundation repair in {place}",
                 "provider": {"@id": "https://www.prairieshieldwaterproofing.com/#business"},
                 "areaServed": {"@type": "City" if c["kind"] == "city" else "AdministrativeArea",
                                "name": place + ("" if c["kind"] == "city" else ", Illinois")}}],
    )


def town_page(t):
    place = t["name"]
    body = prose_section(f"{place} Homes", f"Basement &amp; Foundation Problems in {place}", "local-heading", t["intro"])
    body += warn_section(f"Common in {place}", f"What We Fix Most in {place}", "warns-heading", t["issues"],
                         sub="Seeing one of these? A free inspection will tell you what is causing it.")
    near = [(TOWN_NAMES[s], town_url(s)) for s in t["nearby"]]
    near.append((COUNTY_NAMES[t["county"]], f"{AREAS}{t['county']}/"))
    body += links_section("Nearby", "We Also Serve Nearby", "towns-heading", near)
    body += services_sections(place)
    county = COUNTY_NAMES[t["county"]]
    return dict(
        path=town_url(t["slug"]),
        title=f"{place} Basement Waterproofing &amp; Foundation Repair | Prairie Shield",
        desc=(f"Basement waterproofing, foundation crack repair, sump pumps and masonry in {place}, IL. "
              "Local crews, free estimates and 24/7 emergency service from Prairie Shield."),
        h1=f"Basement Waterproofing &amp; Foundation Repair in {place}, IL",
        lead=t["lead"], tagline=f"Serving {place} &middot; {t['county_name']}",
        crumbs=[("Service Areas", AREAS), (county, f"{AREAS}{t['county']}/"), (place, town_url(t["slug"]))],
        form=f"lead-area-{t['slug']}", form_heading=f"Free Estimate in {place}", service=place,
        nav="subnav-areas", body=body, faqs=t["faqs"], faq_key=f"area-{t['slug']}",
        faq_heading=f"{place} Questions", cta=f"Free Estimates in {place}",
        schema=[{"@type": "Service", "name": f"Basement waterproofing and foundation repair in {place}, Illinois",
                 "provider": {"@id": "https://www.prairieshieldwaterproofing.com/#business"},
                 "areaServed": {"@type": "City", "name": f"{place}, Illinois"}}],
    )


def pages():
    return [county_page(c) for c in COUNTIES] + [town_page(t) for t in TOWNS]
